={
  "model": "qwen2.5:7b",
  "stream": false,
  "prompt": "You are a proposal writer for a digital agency (Nivy International). Draft a service proposal for this lead.

Lead name: {{$json.name}}
Company: {{$json.company}}
Service interest: {{$json.service_type}}
Intent summary: {{$json.intent_summary}}

Return ONLY a valid JSON object with exactly these keys: proposal_title (short), scope_summary (2-3 sentences), deliverables (array of 4-6 short strings), timeline_weeks (integer estimate), pricing_tiers (array of exactly 3 objects each with keys: tier_name, price_inr (integer, realistic for an Indian digital agency), includes (short string)), recommended_tier (one of the 3 tier_name values), email_intro (80-120 words, warm, professional, inviting them to review the attached proposal and book a follow-up call if needed)."
}

parameters.jsCode:
const response = $input.item.json.response || '';
let parsed = {};
try {
  parsed = JSON.parse(response);
} catch (e) {
  const match = response.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : {};
}
const lead = $('Fetch Lead Detail').item.json;
const tiers = Array.isArray(parsed.pricing_tiers) ? parsed.pricing_tiers : [];
const recommended = tiers.find(t => t.tier_name === parsed.recommended_tier) || tiers[0] || { price_inr: 0, tier_name: 'Standard' };
const customThreshold = parseInt($env.PROPOSAL_CUSTOM_THRESHOLD_INR || '150000', 10);

return [{
  json: {
    odoo_lead_id: lead.odoo_lead_id,
    name: lead.name,
    email: lead.email,
    company: lead.company,
    proposal_title: parsed.proposal_title || 'Proposal for ' + lead.company,
    scope_summary: parsed.scope_summary || '',
    deliverables: parsed.deliverables || [],
    timeline_weeks: parsed.timeline_weeks || 4,
    pricing_tiers: tiers,
    recommended_tier: recommended.tier_name,
    recommended_price: recommended.price_inr,
    email_intro: parsed.email_intro || 'Please find our proposal attached.',
    use_custom_pdf: recommended.price_inr >= customThreshold
  }
}];

// Odoo simple quotation ka portal link banao
const quoteId = $input.item.json.result;
return [{
  json: {
    ...$('Parse + Decide Simple vs Custom').item.json,
    proposal_url: `${$env.ODOO_URL}/my/orders/${quoteId}`
  }
}];

// Gotenberg ke liye simple HTML proposal document banao
const d = $('Parse + Decide Simple vs Custom').item.json;
const rows = (d.pricing_tiers || []).map(t => `<tr><td>${t.tier_name}</td><td>Rs. ${t.price_inr}</td><td>${t.includes}</td></tr>`).join('');
const deliverables = (d.deliverables || []).map(x => `<li>${x}</li>`).join('');
const html = `<html><body style="font-family:Arial;padding:40px;">
<h1>${d.proposal_title}</h1>
<p><b>Prepared for:</b> ${d.name} - ${d.company}</p>
<h2>Scope</h2><p>${d.scope_summary}</p>
<h2>Deliverables</h2><ul>${deliverables}</ul>
<h2>Timeline</h2><p>${d.timeline_weeks} weeks (estimated)</p>
<h2>Pricing</h2><table border="1" cellpadding="8" style="border-collapse:collapse;width:100%"><tr><th>Tier</th><th>Price (INR)</th><th>Includes</th></tr>${rows}</table>
<p><i>Recommended: ${d.recommended_tier}</i></p>
</body></html>`;
return [{ json: { ...d, proposal_html: html } }];

const shareUrl = $input.item.json.ocs?.data?.url || '';
return [{
  json: {
    ...$('Parse + Decide Simple vs Custom').item.json,
    proposal_url: shareUrl
  }
}];

