// 3.0.1 security patch glue: build the base accept-link URL as a discrete field
// (previously this was inlined directly into the email text template)
const d = $json;
return [{
  json: {
    ...d,
    accept_url_base: `${$env.PROPOSAL_ACCEPT_BASE_URL}/webhook/proposal-accept?lead_id=${d.odoo_lead_id}`
  }
}];

const crypto = require('crypto');

const leadId = String($json.odoo_lead_id ?? '');
if (!leadId) { throw new Error('3.0.1.1: odoo_lead_id is required'); }

const secret = $env.PROPOSAL_ACCEPT_HMAC_SECRET;
if (!secret) { throw new Error('3.0.1.1: PROPOSAL_ACCEPT_HMAC_SECRET is not configured'); }

const expiresAt = Math.floor(Date.now() / 1000) + (7 * 24 * 60 * 60);
const payload = `${leadId}.${expiresAt}`;
const signature = crypto.createHmac('sha256', secret).update(payload, 'utf8').digest('hex');
const acceptToken = `${payload}.${signature}`;

return [{ json: { ...$json, accept_token: acceptToken } }];

const baseUrl = String($json.accept_url_base ?? '');
const token = String($json.accept_token ?? '');
if (!baseUrl) { throw new Error('3.0.1.2: accept_url_base is missing'); }
if (!token) { throw new Error('3.0.1.2: accept_token is missing'); }

const separator = baseUrl.includes('?') ? '&' : '?';
const acceptUrl = `${baseUrl}${separator}accept_token=${encodeURIComponent(token)}`;

return [{ json: { ...$json, proposal_accept_url: acceptUrl } }];
